static void mlx5e_tc_del_flow(struct mlx5e_priv *priv,
			      struct mlx5e_tc_flow *flow)
{
	if (mlx5e_is_eswitch_flow(flow)) {
		struct mlx5_devcom *devcom = flow->priv->mdev->priv.devcom;
		struct mlx5_eswitch *peer_esw;

